const themes = [
  { category: 'Open Source Tutorials', instruction: 'Pick a well-known open source program/project and write a practical tutorial: how to install, configure, and use it, plus use cases and tips.' },
  { category: 'Hosting Reviews', instruction: 'Write a guide to hosting / virtual hosting / VPS selection or review. Important: do not fabricate specific prices, benchmark scores, configuration numbers, or vendor promises. If you mention specific specs or time-sensitive info, say "refer to official docs/website". Focus on selection criteria, use cases, and real-world considerations.' },
  { category: 'Server Administration', instruction: 'Write a hands-on server administration tutorial, e.g. common Linux commands, daily checks, security hardening, backup & restore, log analysis.' },
  { category: 'WordPress Optimization', instruction: 'Write a WordPress optimization tutorial, e.g. performance tuning, caching configuration, SEO, security hardening, plugin recommendations.' },
  { category: 'Online Tools Tutorials', instruction: 'Write a tutorial for a useful online tool: its features, how to use it, pros and cons, and things to watch out for.' },
  { category: 'Python/PHP Basics', instruction: 'Write a Python or PHP beginner tutorial, e.g. environment setup, basic syntax, common libraries/frameworks, a small hands-on project.' }
];
const pick = themes[Math.floor(Math.random() * themes.length)];
return [{ json: { category: pick.category, instruction: pick.instruction } }];

const raw = $json.output || '{}';
let parsed = {};
let s = String(raw).trim();
const m = s.match(/```(?:json)?\s*([\s\S]*?)```/);
if (m) s = m[1].trim();
const start = s.indexOf('{');
const end = s.lastIndexOf('}');
if (start !== -1 && end !== -1) s = s.slice(start, end + 1);
try {
  parsed = JSON.parse(s);
} catch (e) {
  throw new Error('AI output is not valid JSON: ' + e.message + ' | raw: ' + raw);
}
let title = String(parsed.title || '').trim();
let slug = String(parsed.slug || '').trim();
if (!slug && title) {
  slug = title.toLowerCase().replace(/[^\w\u4e00-\u9fa5]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
}
return [{ json: {
  title: title,
  slug: slug,
  excerpt: String(parsed.excerpt || '').trim(),
  content: String(parsed.content || '').trim(),
  category: String(parsed.category || 'Uncategorized').trim(),
  tags: Array.isArray(parsed.tags) ? parsed.tags.map(t => String(t).trim()).filter(Boolean) : []
} }];

const posts = $input.all();
const art = $('Code - 解析AI输出').all()[0].json;
const targetSlug = String(art.slug || '').trim();
const isDuplicate = Boolean(targetSlug) && posts.some(item => String(item.json?.slug || '').trim() === targetSlug);
return [{ json: { ...art, isDuplicate } }];

const art = $('Code - 判断重复').first().json;
const defaults = ['Tech Tutorials', 'Practical Tips', 'Web Hosting'];
const tagNames = [...new Set((Array.isArray(art.tags) ? art.tags : []).map(tag => String(tag).trim()).filter(Boolean))];
for (const tag of defaults) {
  if (tagNames.length >= 3) break;
  if (!tagNames.includes(tag)) tagNames.push(tag);
}
return [{ json: { ...art, category: String(art.category || 'Uncategorized').trim(), tagNames } }];

const response = $input.first().json;
const art = $('Code - 准备术语').first().json;
const termId = response.id ?? response.term_id ?? response.data?.term_id ?? response.error?.data?.term_id ?? response.error?.response?.data?.term_id;
const categoryId = Number(termId);
if (!Number.isInteger(categoryId) || categoryId <= 0) throw new Error('Failed to create or get category term_id: ' + JSON.stringify(response));
return [{ json: { ...art, categoryId } }];

const item = $json;
const names = Array.isArray(item.tagNames) ? item.tagNames : [];
return names.map(tagName => ({ json: { ...item, tagName } }));

const art = $('Code - 取得分类ID').first().json;
const finalTagIds = [...new Set($input.all().map(item => {
  const response = item.json;
  return Number(response.id ?? response.term_id ?? response.data?.term_id ?? response.error?.data?.term_id ?? response.error?.response?.data?.term_id);
}).filter(id => Number.isInteger(id) && id > 0))];
if (finalTagIds.length !== art.tagNames.length) throw new Error('Failed to create or get all tag term_ids');
return [{ json: { ...art, finalTagIds } }];

const item = $json;
return [{ json: {
  title: item.title,
  content: item.content,
  slug: item.slug,
  excerpt: item.excerpt,
  status: 'publish',
  comment_status: 'open',
  categories: item.categoryId ? [Number(item.categoryId)] : [1],
  tags: Array.isArray(item.finalTagIds) ? item.finalTagIds.map(Number) : []
} }];
